function validate([prices, money]) {
  if (!Array.isArray(prices) || prices.length < 2 || prices.length > 50) return 'prices needs 2 to 50 values.';
  if (prices.some(p => !Number.isInteger(p) || p < 1 || p > 100)) return 'Each price is an integer from 1 to 100.';
  if (!Number.isInteger(money) || money < 1 || money > 100) return 'money is an integer from 1 to 100.';
  return null;
}

