function buyChoco(prices, money) {
  const sorted = [...prices].sort((a, b) => a - b);
  const cheapest = sorted[0];
  const second = sorted[1];
  const cost = cheapest + second;
  if (cost <= money) {
    return money - cost;
  }
  return money;
}

brute:
function buyChoco(prices, money) {
  // Try every pair and keep the largest leftover that is not negative.
  let best = -1;
  for (let i = 0; i < prices.length; i++)
    for (let j = i + 1; j < prices.length; j++) {
      const left = money - prices[i] - prices[j];
      if (left >= 0 && left > best) best = left;
    }
  return best === -1 ? money : best;
}

