function generate(rand, size) {
  if (size === 'large') {
    const prices = Array.from({ length: 50 }, () => 1 + Math.floor(rand() * 100));
    return [prices, 1 + Math.floor(rand() * 100)];
  }
  const n = 2 + Math.floor(rand() * 5);
  const top = rand() < 0.5 ? 10 : 100;
  const prices = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const money = 1 + Math.floor(rand() * Math.min(100, 2 * top));
  return [prices, money];
}
